  1	export type RoamMode = "stay" | "wander" | "cursor" | "climb";
  2	
  3	export interface PetInstance {
  4	  id: string;
  5	  name: string;
  6	  spriteSlug: string;
  7	  visible: boolean;
  8	  size: number;
  9	  roamEnabled: boolean;
 10	  roamMode: RoamMode;
 11	  roamSpeed: number;
 12	  reactsToActivity: boolean;
 13	}
 14	
 15	export interface PetStore {
 16	  version: 1;
 17	  selectedId: string | null;
 18	  instances: PetInstance[];
 19	}
 20	
 21	export interface LegacyPet {
 22	  slug: string;
 23	  name: string;
 24	}
 25	
 26	const STORE_KEY = "ap_pet_instances";
 27	const STORE_VERSION = 1 as const;
 28	const LEGACY_INSTANCE_ID = "legacy-pet";
 29	const VALID_ROAM_MODES: RoamMode[] = ["stay", "wander", "cursor", "climb"];
 30	
 31	export function emptyPetStore(): PetStore {
 32	  return { version: STORE_VERSION, selectedId: null, instances: [] };
 33	}
 34	
 35	function clamp(value: number, min: number, max: number, fallback: number): number {
 36	  return Number.isFinite(value) ? Math.max(min, Math.min(max, Math.round(value))) : fallback;
 37	}
 38	
 39	function normalizeInstance(value: unknown): PetInstance | null {
 40	  if (!value || typeof value !== "object") return null;
 41	  const raw = value as Partial<PetInstance>;
 42	  if (typeof raw.id !== "string" || !raw.id || typeof raw.spriteSlug !== "string" || !raw.spriteSlug) return null;
 43	  const roamMode = VALID_ROAM_MODES.includes(raw.roamMode as RoamMode) ? raw.roamMode as RoamMode : "wander";
 44	  return {
 45	    id: raw.id,
 46	    name: typeof raw.name === "string" ? raw.name.slice(0, 40) : raw.spriteSlug,
 47	    spriteSlug: raw.spriteSlug,
 48	    visible: raw.visible !== false,
 49	    size: clamp(Number(raw.size), 70, 130, 100),
 50	    roamEnabled: raw.roamEnabled !== false,
 51	    roamMode,
 52	    roamSpeed: clamp(Number(raw.roamSpeed), 1, 10, 5),
 53	    reactsToActivity: raw.reactsToActivity === true,
 54	  };
 55	}
 56	
 57	export function parsePetStore(value: unknown): PetStore | null {
 58	  if (!value || typeof value !== "object") return null;
 59	  const raw = value as Partial<PetStore>;
 60	  if (raw.version !== STORE_VERSION || !Array.isArray(raw.instances)) return null;
 61	  const ids = new Set<string>();
 62	  const instances = raw.instances.flatMap((instance) => {
 63	    const normalized = normalizeInstance(instance);
 64	    if (!normalized || ids.has(normalized.id)) return [];
 65	    ids.add(normalized.id);
 66	    return [normalized];
 67	  });
 68	  const selectedId = typeof raw.selectedId === "string" && ids.has(raw.selectedId)
 69	    ? raw.selectedId
 70	    : instances[0]?.id ?? null;
 71	  return { version: STORE_VERSION, selectedId, instances };
 72	}
 73	
 74	export function loadPetStore(): PetStore | null {
 75	  try {
 76	    return parsePetStore(JSON.parse(localStorage.getItem(STORE_KEY) || "null"));
 77	  } catch {
 78	    return null;
 79	  }
 80	}
 81	
 82	export function savePetStore(store: PetStore): void {
 83	  localStorage.setItem(STORE_KEY, JSON.stringify(store));
 84	}
 85	
 86	/**
 87	 * Converts the old selected-sprite concept once. A persisted empty store is a
 88	 * deliberate user choice and must never recreate the old pet.
 89	 */
 90	export function migrateLegacyPetStore(store: PetStore | null, legacy: LegacyPet | null): PetStore {
 91	  if (store) return store;
 92	  if (!legacy?.slug) return emptyPetStore();
 93	  const instance: PetInstance = {
 94	    id: LEGACY_INSTANCE_ID,
 95	    name: legacy.name.trim().slice(0, 40) || legacy.slug,
 96	    spriteSlug: legacy.slug,
 97	    visible: true,
 98	    size: 100,
 99	    roamEnabled: true,
100	    roamMode: "wander",
101	    roamSpeed: 5,
102	    reactsToActivity: true,
103	  };
104	  return { version: STORE_VERSION, selectedId: instance.id, instances: [instance] };
105	}
106	
107	export function initializePetStore(legacy: LegacyPet | null): PetStore {
108	  const store = migrateLegacyPetStore(loadPetStore(), legacy);
109	  savePetStore(store);
110	  return store;
111	}
112	
113	export function createPetInstance(store: PetStore, instance: PetInstance): PetStore {
114	  if (store.instances.some((candidate) => candidate.id === instance.id)) {
115	    throw new Error(`duplicate pet instance id: ${instance.id}`);
116	  }
117	  const normalized = normalizeInstance(instance);
118	  if (!normalized) throw new Error("invalid pet instance");
119	  return {
120	    ...store,
121	    selectedId: normalized.id,
122	    instances: [...store.instances, normalized],
123	  };
124	}
125	
126	export function updatePetInstance(
127	  store: PetStore,
128	  id: string,
129	  patch: Partial<Omit<PetInstance, "id">>,
130	): PetStore {
131	  const index = store.instances.findIndex((instance) => instance.id === id);
132	  if (index < 0) throw new Error(`unknown pet instance id: ${id}`);
133	  const updated = normalizeInstance({ ...store.instances[index], ...patch });
134	  if (!updated) throw new Error("invalid pet instance update");
135	  const instances = [...store.instances];
136	  instances[index] = updated;
137	  return { ...store, instances };
138	}
139	
140	export function removePetInstance(store: PetStore, id: string): PetStore {
141	  const instances = store.instances.filter((instance) => instance.id !== id);
142	  if (instances.length === store.instances.length) return store;
143	  return {
144	    ...store,
145	    selectedId: store.selectedId === id ? instances[0]?.id ?? null : store.selectedId,
146	    instances,
147	  };
148	}
149	
150	export function selectPetInstance(store: PetStore, id: string | null): PetStore {
151	  if (id !== null && !store.instances.some((instance) => instance.id === id)) {
152	    throw new Error(`unknown pet instance id: ${id}`);
153	  }
154	  return { ...store, selectedId: id };
155	}
156	
157	export function selectedPetInstance(store: PetStore): PetInstance | null {
158	  return store.instances.find((instance) => instance.id === store.selectedId) ?? null;
159	}
160	
161	export function petInstanceById(store: PetStore, id: string): PetInstance | null {
162	  return store.instances.find((instance) => instance.id === id) ?? null;
163	}
164	
165	export function newPetInstanceId(): string {
166	  return `pet-${crypto.randomUUID().replace(/-/g, "")}`;
167	}
