  3	  createPetInstance,
  4	  emptyPetStore,
  5	  migrateLegacyPetStore,
  6	  removePetInstance,
  7	  updatePetInstance,
  8	  type PetInstance,
  9	} from "./pets";
 10	
 11	function pet(id: string, slug: string, name: string): PetInstance {
 12	  return {
 13	    id,
 14	    name,
 15	    spriteSlug: slug,
 16	    visible: true,
 17	    size: 100,
 18	    roamEnabled: true,
 19	    roamMode: "wander",
 20	    roamSpeed: 5,
 21	    reactsToActivity: false,
 22	  };
 23	}
 24	
 25	describe("desktop pet instance model", () => {
 26	  it("migrates the legacy selected pet into one normal desktop instance", () => {
 27	    const store = migrateLegacyPetStore(null, { slug: "cat", name: "Miso" });
 28	
 29	    expect(store).toEqual({
 30	      version: 1,
 31	      selectedId: "legacy-pet",
 32	      instances: [{
 33	        ...pet("legacy-pet", "cat", "Miso"),
 34	        reactsToActivity: true,
 35	      }],
 36	    });
 37	  });
 38	
 39	  it("keeps an explicitly empty instance store empty after the legacy migration", () => {
 40	    const empty = emptyPetStore();
 41	
 42	    const store = migrateLegacyPetStore(empty, { slug: "cat", name: "Miso" });
 43	
 44	    expect(store).toEqual(empty);
 45	  });
 46	
 47	  it("selects a newly created instance for immediate editing", () => {
 48	    let store = emptyPetStore();
 49	    store = createPetInstance(store, pet("miso", "cat", "Miso"));
 50	    store = createPetInstance(store, pet("nori", "cat", "Nori"));
 51	
 52	    expect(store.selectedId).toBe("nori");
 53	  });
 54	
 55	  it("keeps identical sprite instances independent when one is renamed or removed", () => {
 56	    let store = emptyPetStore();
 57	    store = createPetInstance(store, pet("miso", "cat", "Miso"));
 58	    store = createPetInstance(store, pet("nori", "cat", "Nori"));
 59	    store = updatePetInstance(store, "miso", { name: "Miso Prime", size: 125 });
 60	
 61	    expect(store.instances).toEqual([
 62	      { ...pet("miso", "cat", "Miso"), name: "Miso Prime", size: 125 },
 63	      pet("nori", "cat", "Nori"),
 64	    ]);
 65	
 66	    store = removePetInstance(store, "miso");
 67	    expect(store.selectedId).toBe("nori");
 68	    expect(store.instances).toEqual([pet("nori", "cat", "Nori")]);
 69	  });
 70	});

