  1	import { listen, emit } from "@tauri-apps/api/event";
  2	import "./styles.css";
  3	
  4	import { invoke } from "@tauri-apps/api/core";
  5	import { getCurrentWindow } from "@tauri-apps/api/window";
  6	import { Pet } from "./pet";
  7	import { ActivityStore, type ActivityEventPayload } from "./state";
  8	import { BubbleRenderer, invalidateBubbleConfig } from "./bubble";
  9	import { libraryUrlForSlug } from "./catalog";
 10	import { t, setLang, type Lang } from "./i18n";
 11	import { bubbleLines, PET_CHAT } from "./activity";
 12	import * as care from "./care";
 13	import { loadPetStore, petInstanceById, type PetInstance } from "./pets";
 14	import { initRoam, setDragging, setMood } from "./roam";
 15	
 16	const MY_INSTANCE_ID = new URLSearchParams(location.search).get("pet");
 17	const MY_LABEL = getCurrentWindow().label;
 18	
 19	function readPetInstance(): PetInstance | null {
 20	  if (!MY_INSTANCE_ID) return null;
 21	  const store = loadPetStore();
 22	  return store ? petInstanceById(store, MY_INSTANCE_ID) : null;
 23	}
 24	
 25	let cachedInstance = readPetInstance();
 26	
 27	function myPetInstance(): PetInstance | null {
 28	  return cachedInstance;
 29	}
 30	
 31	function refreshPetInstance(): void {
 32	  cachedInstance = readPetInstance();
 33	}
 34	
 35	const canvas = document.getElementById("pet") as HTMLCanvasElement;
 36	const bubbleEl = document.getElementById("bubble") as HTMLDivElement;
 37	const pet = new Pet(canvas);
 38	const store = new ActivityStore();
 39	const bubble = new BubbleRenderer(bubbleEl);
 40	initRoam(pet, () => {
 41	  const instance = myPetInstance();
 42	  return instance
 43	    ? { enabled: instance.roamEnabled, mode: instance.roamMode, speed: instance.roamSpeed }
 44	    : { enabled: false, mode: "stay", speed: 1 };
 45	});
 46	
 47	// --- bubble appearance (theme / opacity / fonts) ------------------------------
 48	const FONT_FAMILIES: Record<string, string> = {
 49	  system: '"Segoe UI", system-ui, sans-serif',
 50	  rounded: '"Segoe UI Rounded", "Nunito", "Segoe UI", sans-serif',
 51	  mono: 'Consolas, "Courier New", monospace',
 52	};
 53	
 54	function applyBubble() {
 55	  let theme = localStorage.getItem("ap_theme") || "dark";
 56	  if (theme === "system") theme = matchMedia("(prefers-color-scheme: light)").matches ? "light" : "dark";
 57	  const op = (parseInt(localStorage.getItem("ap_opacity") || "92", 10) || 92) / 100;
 58	  const r = document.documentElement.style;
 59	  if (theme === "light") {
 60	    r.setProperty("--bubble-bg", `rgba(255,255,255,${op})`);
 61	    r.setProperty("--bubble-fg", "#3A2C1A");
 62	    r.setProperty("--bubble-border", "rgba(0,0,0,0.08)");
 63	  } else {
 64	    r.setProperty("--bubble-bg", `rgba(26,20,13,${op})`);
 65	    r.setProperty("--bubble-fg", "#ffffff");
 66	    r.setProperty("--bubble-border", "rgba(255,255,255,0.10)");
 67	  }
 68	  r.setProperty("--bubble-font-size", `${parseInt(localStorage.getItem("ap_font_size") || "12", 10) || 12}px`);
 69	  r.setProperty("--bubble-font-family", FONT_FAMILIES[localStorage.getItem("ap_font_family") || "system"] ?? FONT_FAMILIES.system);
 70	}
 71	applyBubble();
 72	
 73	// Pet size + idle bob FX. Size belongs to the displayed instance, so two
 74	// instances using the same spritesheet remain independently configurable.
 75	function applyPet() {
 76	  const size = (myPetInstance()?.size ?? 100) / 100;
 77	  canvas.style.width = `${Math.round(160 * size)}px`;
 78	  canvas.style.height = `${Math.round(180 * size)}px`;
