363	let lastHitSig = "";
364	function reportHitRect() {
365	  const d = window.devicePixelRatio || 1;
366	  const rects: { left: number; top: number; right: number; bottom: number }[] = [];
367	  if (!bubbleEl.hidden) {
368	    const b = bubbleEl.getBoundingClientRect();
369	    if (b.width > 0) rects.push({ left: b.left, top: b.top, right: b.right, bottom: b.bottom });
370	  }
371	  const cr = canvas.getBoundingClientRect();
372	  const sr = pet.spriteRect;
