357	// Report the interactive region (physical px) for Windows click-through: the
358	// union of the SPRITE's true bounds and the visible bubble, not the whole
359	// canvas, so the empty space beside the pet passes clicks to apps below.
360	// Every pet window (main, project, extra) registers under its own label so
361	// the Rust loop can manage click-through independently per window.
362	const petRoot = document.getElementById("pet-root") as HTMLElement;
363	let lastHitSig = "";
364	function reportHitRect() {
365	  const d = window.devicePixelRatio || 1;
366	  const rects: { left: number; top: number; right: number; bottom: number }[] = [];
367	  if (!bubbleEl.hidden) {
368	    const b = bubbleEl.getBoundingClientRect();
369	    if (b.width > 0) rects.push({ left: b.left, top: b.top, right: b.right, bottom: b.bottom });
370	  }
371	  const cr = canvas.getBoundingClientRect();
372	  const sr = pet.spriteRect;
373	  if (sr && canvas.width > 0) {
374	    const kx = cr.width / canvas.width;
375	    const ky = cr.height / canvas.height;
376	    rects.push({
377	      left: cr.left + sr.x * kx,
378	      top: cr.top + sr.y * ky,
379	      right: cr.left + (sr.x + sr.w) * kx,
380	      bottom: cr.top + (sr.y + sr.h) * ky,
381	    });
382	  } else {
383	    rects.push({ left: cr.left, top: cr.top, right: cr.right, bottom: cr.bottom });
384	  }
385	  const left = Math.min(...rects.map((r) => r.left));
386	  const top = Math.min(...rects.map((r) => r.top));
387	  const right = Math.max(...rects.map((r) => r.right));
388	  const bottom = Math.max(...rects.map((r) => r.bottom));
389	  const sig = [left, top, right, bottom].map((v) => Math.round(v)).join(",");
390	  if (sig === lastHitSig) return;
391	  lastHitSig = sig;
392	  invoke("set_hit_rect", { label: MY_LABEL, x: left * d, y: top * d, w: (right - left) * d, h: (bottom - top) * d })
393	    .catch((err) => invoke("log_debug", { msg: `set_hit_rect failed: ${err}` }).catch(() => {}));
394	}
395	new ResizeObserver(reportHitRect).observe(petRoot);
