157	type ReleaseContext = {
158	  config: Config;
159	  environment: Environment;
160	};
161	
162	type ConfigReader = () => Config;
163	type EnvironmentReader = (includeSystemWindows: boolean) => Promise<Environment | null>;
164	
165	export async function resolveReleaseContext(
166	  getConfig: ConfigReader = loadConfig,
167	  getEnvironment: EnvironmentReader = fetchEnvironment,
168	): Promise<ReleaseContext | null> {
169	  let config = getConfig();
170	  const includedSystemWindows = config.mode === "climb";
171	  let environment = await getEnvironment(includedSystemWindows);
172	  if (!environment) return null;
173	
174	  config = getConfig();
175	  if (config.mode === "climb" && !includedSystemWindows) {
176	    environment = await getEnvironment(true);
177	    if (!environment) return null;
178	  }
179	
180	  return { config: getConfig(), environment };
181	}
182	
183	async function handleDragRelease(vel: { vx: number; vy: number }): Promise<void> {
184	  const context = await resolveReleaseContext();
185	  if (!context) return;
186	  const { config: cfg, environment: env } = context;
187	
188	  if (cfg.mode === "climb" && env.windows.length > 0) {
189	    const surfaces = env.windows.map((w) => w.rect);
190	    await applyFall(vel.vx, env.workArea, surfaces, petRef, stop);
191	  } else {
192	    await applyThrow(vel.vx, vel.vy, env.workArea, petRef, stop);
193	  }
194	}
195	
196	async function loop(): Promise<void> {
197	  while (!stopRequested) {
198	    const active = await tick();
199	    await sleep(active ? TICK_MS : IDLE_TICK_MS);
200	  }
201	  petRef?.clearRow();
202	}
203	
204	export function initEngine(pet: Pet): void {
205	  if (petRef) return;
206	  petRef = pet;
207	  stopRequested = false;
208	  lastMoveTs = Date.now();
209	  mood = "idle";
210	  sleeping = false;
211	  void loop();
212	}
213	
214	export function destroyEngine(): void {
215	  stopRequested = true;
216	  cancelThrow();
217	  petRef = null;
218	}
219	
220	export function setDragging(isDragging: boolean): void {
221	  dragging = isDragging;
222	  setNativeDragTracking(isDragging);
223	  if (isDragging) {
224	    cancelThrow();
225	    clearSamples();
226	    wake();
227	    releasePending = false;
228	  } else if (petRef) {
229	    releasePending = true;
230	  }
231	}
  1	// Movement strategies. Each mode is a pure function: given the current
  2	// position and environment, return the next position (and animate the pet).
  3	// The engine drives the tick loop; modes stay stateless where possible.
  4	
  5	import { cursorPosition } from "@tauri-apps/api/window";
  6	import { invoke } from "@tauri-apps/api/core";
  7	import type { Pet } from "../pet";
  8	import type { Environment, Point, Rect, RoamMode } from "./types";
  9	import {
 10	  DT_SEC,
 11	  IDLE_MS_MAX,
 12	  IDLE_MS_MIN,
 13	  MARGIN,
 14	  WIN_H,
 15	  WIN_W,
 16	  clampToBounds,
 17	  loadConfig,
 18	  pxPerSec,
 19	} from "./types";
 20	
 21	const ROW_RIGHT = 1;
 22	const ROW_LEFT = 2;
 23	const ARRIVAL_DISTANCE = 8;
 24	
 25	type HorizontalDirection = -1 | 1;
 26	
 27	let climbDirection: HorizontalDirection | null = null;
 28	
 29	// Temporary field diagnostics (throttled, see engine.ts).
 30	let lastModeDiagTs = 0;
 31	function modeDiag(msg: string): void {
 32	  const now = Date.now();
 33	  if (now - lastModeDiagTs < 300) return;
 34	  lastModeDiagTs = now;
 35	  void invoke("log_debug", { msg: `roam-mode: ${msg}` }).catch(() => {});
 36	}
 37	
 38	export interface ModeContext {
 39	  env: Environment;
 40	  pos: Point;
 41	  pet: Pet | null;
 42	}
 43	
 44	/// Dispatches to the active mode and returns the next position (or the
 45	/// unchanged position if the mode didn't move). Each mode handles its own
 46	/// animation row; if no movement happens, the caller clears the row.
 47	export async function runMode(mode: RoamMode, ctx: ModeContext): Promise<Point> {
 48	  if (mode !== "climb") {
 49	    climbDirection = null;
 50	    restUntil = 0;
 51	  }
 52	  switch (mode) {
 53	    case "stay": return ctx.pos;
 54	    case "cursor": return followCursor(ctx);
 55	    case "climb": return climb(ctx);
 56	    case "wander":
 57	    default: return wander(ctx);
 58	  }
 59	}
 60	
 61	/// Chase the mouse cursor. Stops beside it so it doesn't cover the pointer.
 62	async function followCursor(ctx: ModeContext): Promise<Point> {
 63	  const { env, pos, pet } = ctx;
 64	  try {
 65	    const sf = (await import("@tauri-apps/api/window")).getCurrentWindow();
 66	    const factor = await sf.scaleFactor();
 67	    const cur = await cursorPosition();
 68	    const target = {
 69	      x: cur.x / factor - WIN_W / 2,
 70	      y: cur.y / factor - WIN_H + 20,
 71	    };
 72	    return moveToward(target, pos, env.workArea, pet);
 73	  } catch {
 74	    return pos;
 75	  }
 76	}
 77	
 78	/// Persistent wander target. The engine calls wander() once per tick (30ms),
 79	/// so the target must survive across calls , otherwise the pet picks a new
 80	/// random destination every tick and jitters in place instead of walking.
 81	let wanderTarget: Point | null = null;
 82	
 83	/// Shared "resting until" deadline (ms timestamp). Set by a mode when the pet
 84	/// reaches a destination / edge and should pause. The engine loop keeps
 85	/// ticking at 30ms while resting, so drag, mood changes, and mode switches
 86	/// stay responsive , the modes just no-op until the deadline passes.
 87	let restUntil = 0;
 88	
 89	function inBounds(p: Point, bounds: Rect): boolean {
 90	  return p.x >= bounds.left && p.x <= bounds.right - WIN_W
 91	      && p.y >= bounds.top && p.y <= bounds.bottom - WIN_H;
 92	}
 93	
 94	/// Random walk within the work area. Walks to a target, idles, picks another.
 95	/// The target persists across ticks so the pet actually reaches it. Idling is
 96	/// done by setting `restUntil` (no blocking sleep) so the engine stays live.
 97	function wander(ctx: ModeContext): Point {
 98	  if (loadConfig().mode !== "wander") {
 99	    wanderTarget = null;
100	    restUntil = 0;
101	    return ctx.pos;
102	  }
103	  return advanceWander(ctx);
104	}
105	
106	function fallbackWander(ctx: ModeContext): Point {
107	  restUntil = 0;
108	  return advanceWander(ctx);
109	}
110	
111	function advanceWander(ctx: ModeContext): Point {
112	  const { env, pos, pet } = ctx;
113	  if (Date.now() < restUntil) return pos;
114	  if (!wanderTarget || !inBounds(wanderTarget, env.workArea)) {
115	    wanderTarget = randomTarget(env.workArea);
116	  }
117	  const target = wanderTarget;
118	
119	  const dx = target.x - pos.x;
120	  const dy = target.y - pos.y;
121	  const dist = Math.hypot(dx, dy);
122	
123	  // Arrival must match moveToward's stopping threshold (ARRIVAL_DISTANCE).
124	  // If this check used a smaller radius (e.g. 6), a target 6–8px away would
125	  // make moveToward stop without advanceWander picking a new target, and the
126	  // pet would stand still forever.
127	  if (dist < ARRIVAL_DISTANCE) {
128	    wanderTarget = null;
129	    restUntil = Date.now() + IDLE_MS_MIN + Math.random() * (IDLE_MS_MAX - IDLE_MS_MIN);
130	    pet?.clearRow();
131	    return pos;
132	  }
133	  return moveToward(target, pos, env.workArea, pet);
134	}
135	
136	/// Climb along the top edges of visible application windows, like Shimeji.
137	/// Moves to the nearest reachable window top before walking its edge, then
138	/// pauses and reverses direction at an edge.
139	async function climb(ctx: ModeContext): Promise<Point> {
140	  const { env, pos, pet } = ctx;
141	  if (env.windows.length === 0) {
142	    climbDirection = null;
143	    modeDiag(`climb: no windows -> wander`);
144	    return fallbackWander(ctx);
145	  }
146	  if (Date.now() < restUntil) {
147	    modeDiag(`climb: resting until ${restUntil} (now ${Date.now()})`);
148	    return pos;
149	  }
150	
151	  const surface = findSurfaceBelow(pos, env);
152	  if (!surface.isWindow || !isStandingOnSurface(pos, surface, env.workArea)) {
153	    climbDirection = null;
154	    const target = nearestClimbTarget(pos, env);
155	    modeDiag(`climb: onSurface=${surface.isWindow} stand=${surface.isWindow && isStandingOnSurface(pos, surface, env.workArea)} target=${target ? `${target.x.toFixed(0)},${target.y.toFixed(0)}` : "null"} pos=${pos.x.toFixed(0)},${pos.y.toFixed(0)}`);
156	    return target ? moveToward(target, pos, env.workArea, pet) : fallbackWander(ctx);
157	  }
158	
159	  const support = surfaceSupportRange(surface.rect, env.workArea);
160	  if (!support) {
161	    climbDirection = null;
162	    modeDiag(`climb: no support`);
163	    return fallbackWander(ctx);
164	  }
165	  const standY = climbTopY(surface.rect, env.workArea);
166	
167	  const dir = climbDirection ?? (Math.random() < 0.5 ? -1 : 1);
168	  climbDirection = dir;
169	  const step = pxPerSec(loadConfig().speed) * DT_SEC;
170	  const nextX = pos.x + dir * step;
171	  const onEdge = nextX < support.left - 2 || nextX > support.right + 2;
172	  modeDiag(`climb: walking dir=${dir} support=[${support.left.toFixed(0)},${support.right.toFixed(0)}] onEdge=${onEdge}`);
173	
174	  if (onEdge) {
175	    restUntil = Date.now() + IDLE_MS_MIN + Math.random() * (IDLE_MS_MAX - IDLE_MS_MIN);
176	    climbDirection = dir === 1 ? -1 : 1;
177	    pet?.clearRow();
178	    return {
179	      x: Math.max(support.left, Math.min(support.right, pos.x)),
180	      y: standY,
181	    };
182	  }
183	
184	  const next = clampToBounds(
185	    { x: nextX, y: standY },
186	    env.workArea,
187	  );
188	  pet?.setRow(dir > 0 ? ROW_RIGHT : ROW_LEFT);
189	  return next;
190	}
191	
192	function moveToward(target: Point, pos: Point, bounds: Rect, pet: Pet | null): Point {
193	  const dx = target.x - pos.x;
194	  const dy = target.y - pos.y;
195	  const dist = Math.hypot(dx, dy);
196	  if (dist < ARRIVAL_DISTANCE) { pet?.clearRow(); return pos; }
197	  const speed = pxPerSec(loadConfig().speed);
198	  const move = Math.min(dist, speed * DT_SEC);
199	  const next = clampToBounds(
200	    { x: pos.x + (dx / dist) * move, y: pos.y + (dy / dist) * move },
201	    bounds,
202	  );
203	  pet?.setRow(dx > 0 ? ROW_RIGHT : ROW_LEFT);
204	  return next;
205	}
206	
207	function randomTarget(bounds: Rect): Point {
208	  const x = bounds.left + MARGIN + Math.random() * Math.max(1, bounds.right - bounds.left - WIN_W - MARGIN * 2);
209	  const y = bounds.top + MARGIN + Math.random() * Math.max(1, bounds.bottom - bounds.top - WIN_H - MARGIN * 2);
210	  return { x, y };
211	}
212	
213	interface SurfaceInfo { rect: Rect; isWindow: boolean }
214	
215	type SurfaceSupport = { left: number; right: number };
216	
217	function surfaceSupportRange(rect: Rect, bounds: Rect): SurfaceSupport | null {
218	  const left = Math.max(bounds.left, rect.left - WIN_W / 2);
219	  const right = Math.min(bounds.right - WIN_W, rect.right - WIN_W / 2);
220	  return left <= right ? { left, right } : null;
221	}
222	
223	/// Logical y for the pet window's TOP edge when standing on this surface.
224	/// A window whose top edge sits too high for the pet to stand on (standing on
225	/// it would push the pet off the top of the screen) is treated as reachable at
226	/// the screen top: the pet is pinned to the top edge instead of falling back
227	/// to random roaming on maximized/fullscreen desktops.
228	function climbTopY(rect: Rect, workArea: Rect): number {
229	  return Math.max(rect.top - WIN_H, workArea.top);
230	}
231	
232	function isStandingOnSurface(pos: Point, surface: SurfaceInfo, workArea: Rect): boolean {
233	  return Math.abs(pos.y - climbTopY(surface.rect, workArea)) < ARRIVAL_DISTANCE;
234	}
235	
236	function nearestClimbTarget(pos: Point, env: Environment): Point | null {
237	  let nearest: Point | null = null;
238	  let nearestDistance = Infinity;
239	
240	  for (const window of env.windows) {
241	    const support = surfaceSupportRange(window.rect, env.workArea);
242	    // climbTopY clamps to the screen top, so only window tops below the
243	    // reachable band are skipped (they would push the pet off the bottom).
244	    const y = climbTopY(window.rect, env.workArea);
245	    if (!support || y > env.workArea.bottom - WIN_H) continue;
246	
247	    const target = { x: Math.max(support.left, Math.min(support.right, pos.x)), y };
248	    const distance = Math.hypot(target.x - pos.x, target.y - pos.y);
249	    if (distance < nearestDistance) {
250	      nearest = target;
251	      nearestDistance = distance;
252	    }
253	  }
254	
255	  return nearest;
256	}
257	
258	function findSurfaceBelow(pos: Point, env: Environment): SurfaceInfo {
259	  // Standing on a window means the pet's top sits exactly at that window's
260	  // climbTopY (within the arrival margin), matching isStandingOnSurface so
261	  // the two can never disagree.
262	  for (const w of env.windows) {
263	    const support = surfaceSupportRange(w.rect, env.workArea);
264	    if (!support || pos.x < support.left - ARRIVAL_DISTANCE || pos.x > support.right + ARRIVAL_DISTANCE) continue;
265	    if (Math.abs(pos.y - climbTopY(w.rect, env.workArea)) < ARRIVAL_DISTANCE) {
266	      return { rect: w.rect, isWindow: true };
267	    }
268	  }
269	  return { rect: env.workArea, isWindow: false };
270	}
  1	// Environment sensing: monitor work area + enumeration of other application
  2	// windows. All geometry is returned in logical pixels so the rest of the roam
  3	// subsystem can stay DPI-agnostic.
  4	
  5	import { currentMonitor, type Monitor } from "@tauri-apps/api/window";
  6	import { invoke } from "@tauri-apps/api/core";
  7	import type { Environment, Rect, SystemWindow } from "./types";
  8	
  9	/// Raw shape returned by the Rust `list_system_windows` command. Coordinates
 10	/// are physical pixels; we convert to logical in `fetchEnvironment`.
 11	interface RawSystemWindow {
 12	  title: string;
 13	  x: number;
 14	  y: number;
 15	  width: number;
 16	  height: number;
 17	}
 18	
 19	function toLogicalRect(rect: RawSystemWindow, sf: number): SystemWindow {
 20	  return {
 21	    title: rect.title,
 22	    rect: {
 23	      left: rect.x / sf,
 24	      top: rect.y / sf,
 25	      right: (rect.x + rect.width) / sf,
 26	      bottom: (rect.y + rect.height) / sf,
 27	    },
 28	  };
 29	}
 30	
 31	// 500ms monitor cache: the monitor rarely changes (only when the user drags
 32	// the pet to another display), and currentMonitor() is an IPC call. Without
 33	// this, N roaming pets fire 2×N×33 IPC calls/sec just for monitor info.
 34	const MONITOR_CACHE_MS = 500;
 35	let monitorCache: { mon: Monitor | null; ts: number } | null = null;
 36	
 37	async function cachedMonitor(): Promise<Monitor | null> {
 38	  const now = Date.now();
 39	  if (monitorCache && now - monitorCache.ts < MONITOR_CACHE_MS) {
 40	    return monitorCache.mon;
 41	  }
 42	  try {
 43	    const m = await currentMonitor();
 44	    monitorCache = { mon: m, ts: now };
 45	    return m;
 46	  } catch {
 47	    return null;
 48	  }
 49	}
 50	
 51	// 500ms system-windows cache: list_system_windows is an IPC call that enumerates
 52	// every visible window. Other apps' window positions change far less often than
 53	// the 30ms roam tick, so caching avoids ~33 IPC calls/sec per roaming pet. The
 54	// cache is keyed by the monitor scale factor so a monitor switch still refetches.
 55	const WIN_CACHE_MS = 500;
 56	let winCache: { sf: number; windows: SystemWindow[]; ts: number } | null = null;
 57	
 58	async function fetchSystemWindows(sf: number): Promise<SystemWindow[]> {
 59	  const now = Date.now();
 60	  if (winCache && winCache.sf === sf && now - winCache.ts < WIN_CACHE_MS) {
 61	    return winCache.windows;
 62	  }
 63	  try {
 64	    const raw = await invoke<RawSystemWindow[]>("list_system_windows");
 65	    if (!Array.isArray(raw)) return winCache?.windows ?? [];
 66	    const windows = raw
 67	      .filter((w) => w.width > 40 && w.height > 40)
 68	      .map((w) => toLogicalRect(w, sf));
 69	    winCache = { sf, windows, ts: now };
 70	    return windows;
 71	  } catch {
 72	    return winCache?.windows ?? [];
 73	  }
 74	}
 75	
 76	export function invalidateEnvironmentCache(): void {
 77	  winCache = null;
 78	  monitorCache = null;
 79	}
 80	
 81	export async function fetchEnvironment(includeSystemWindows = false): Promise<Environment | null> {
 82	  try {
 83	    // Single currentMonitor() call (cached) instead of the previous two.
 84	    const m = await cachedMonitor();
 85	    if (!m || !m.workArea) return null;
 86	    const sf = m.scaleFactor || 1;
 87	    const wa = m.workArea;
 88	    const workArea: Rect = {
 89	      left: wa.position.x / sf,
 90	      top: wa.position.y / sf,
 91	      right: (wa.position.x + wa.size.width) / sf,
 92	      bottom: (wa.position.y + wa.size.height) / sf,
 93	    };
 94	
 95	    const windows = includeSystemWindows ? await fetchSystemWindows(sf) : [];
 96	    return { workArea, windows };
 97	  } catch (e) {
 98	    void invoke("log_debug", { msg: `roam: environment error: ${e}` }).catch(() => {});
 99	    return null;
100	  }
101	}

