 83	/// One engine tick. Priority: throw > drag-sample > drag-release > mood-pause > sleep > mode.
 84	/// Returns true when the pet is actively moving/interacting and needs the fast
 85	/// (30ms) tick; false when resting/sleeping/stationary so the loop can use the
 86	/// idle (200ms) tick and skip most IPC calls.
 87	async function tick(): Promise<boolean> {
 88	  if (isThrowing()) return true;
 89	  if (dragging) {
 90	    const pos = await currentLogicalPos();
 91	    if (pos) recordSample(pos);
 92	    return true;
 93	  }
 94	  if (releasePending) {
 95	    releasePending = false;
 96	    const vel = releaseVelocity();
 97	    clearSamples();
 98	    if (vel && Math.hypot(vel.vx, vel.vy) > THROW_MIN_SPEED) {
 99	      wake();
100	      await handleDragRelease(vel);
101	      return true;
102	    }
103	  }
104	
105	  // Mood-driven freeze: keep the pet still while the user needs to see the
106	  // bubble or the celebrate burst. Throws and drags above still work.
107	  if (MOOD_PAUSES_ROAM.has(mood)) {
108	    wake();
109	    petRef?.clearRow();
110	    return false;
111	  }
112	
113	  const cfg = loadConfig();
114	  if (!cfg.enabled || cfg.mode === "stay") {
115	    handleStationary();
116	    return false;
117	  }
118	
119	  wake();
120	  const moved = await stepMode(cfg.mode);
121	  if (!moved && mood === "idle" && Date.now() - lastMoveTs > SLEEP_AFTER_MS) {
122	    enterSleep();
123	  }
124	  return moved;
125	}
