165	export async function resolveReleaseContext(
166	  getConfig: ConfigReader = loadConfig,
167	  getEnvironment: EnvironmentReader = fetchEnvironment,
168	): Promise<ReleaseContext | null> {
169	  let config = getConfig();
170	  const includedSystemWindows = config.mode === "climb";
171	  let environment = await getEnvironment(includedSystemWindows);
172	  if (!environment) return null;
173	
174	  config = getConfig();
175	  if (config.mode === "climb" && !includedSystemWindows) {
176	    environment = await getEnvironment(true);
177	    if (!environment) return null;
178	  }
