183	async function handleDragRelease(vel: { vx: number; vy: number }): Promise<void> {
184	  const context = await resolveReleaseContext();
185	  if (!context) return;
186	  const { config: cfg, environment: env } = context;
187	
188	  if (cfg.mode === "climb" && env.windows.length > 0) {
189	    const surfaces = env.windows.map((w) => w.rect);
190	    await applyFall(vel.vx, env.workArea, surfaces, petRef, stop);
191	  } else {
192	    await applyThrow(vel.vx, vel.vy, env.workArea, petRef, stop);
193	  }
