204	export function initEngine(pet: Pet): void {
205	  if (petRef) return;
206	  petRef = pet;
207	  stopRequested = false;
208	  lastMoveTs = Date.now();
209	  mood = "idle";
210	  sleeping = false;
211	  void loop();
212	}
