  2	// position and environment, return the next position (and animate the pet).
  3	// The engine drives the tick loop; modes stay stateless where possible.
  4	
  5	import { cursorPosition } from "@tauri-apps/api/window";
  6	import { invoke } from "@tauri-apps/api/core";
  7	import type { Pet } from "../pet";
  8	import type { Environment, Point, Rect, RoamMode } from "./types";
  9	import {
 10	  DT_SEC,
 11	  IDLE_MS_MAX,
 12	  IDLE_MS_MIN,
 13	  MARGIN,
 14	  WIN_H,
 15	  WIN_W,
 16	  clampToBounds,
 17	  loadConfig,
 18	  pxPerSec,
 19	} from "./types";
 20	
 21	const ROW_RIGHT = 1;
 22	const ROW_LEFT = 2;
 23	const ARRIVAL_DISTANCE = 8;
 24	
 25	type HorizontalDirection = -1 | 1;
 26	
 27	let climbDirection: HorizontalDirection | null = null;
 28	
 29	// Temporary field diagnostics (throttled, see engine.ts).
 30	let lastModeDiagTs = 0;
 31	function modeDiag(msg: string): void {
 32	  const now = Date.now();
 33	  if (now - lastModeDiagTs < 300) return;
 34	  lastModeDiagTs = now;
 35	  void invoke("log_debug", { msg: `roam-mode: ${msg}` }).catch(() => {});
 36	}
