113	export class Pet {
114	  private ctx: CanvasRenderingContext2D;
115	  private img = new Image();
116	  private loaded = false;
117	  private loadedUrl: string | null = null;
118	  private loadVersion = 0;
119	  private clips: Rect[][] = [];
120	  private frame = 0;
121	  private row = 0;
122	  private overrideRow: number | null = null;
123	  /// Idle-playlist row. Separate from overrideRow so roaming sleep overrides
124	  /// can still take precedence, and the playlist resumes cleanly after wake.
125	  private idleRow: number | null = null;
126	  private idleTimer: number | null = null;
127	  private idleIntervalMs = 0;
128	  private idleClips: number[] = [];
129	  private idleIndex = 0;
130	  private lastDrawnRow = 0;
131	  private fps = 3;
132	  /// Unused space above the sprite, as a fraction of canvas height. The bubble
133	  /// uses it to sit right above the pet's head instead of the canvas top.
134	  headroom = 0;
135	  /// Last drawn sprite rect in backing-store pixels , the pet's true bounds.
136	  spriteRect: { x: number; y: number; w: number; h: number } | null = null;
137	
138	  /// True when a CSS-pixel point inside the canvas hits the SPRITE (alpha
139	  /// test), so clicks on the empty area around the pet don't drag the window.
140	  hitTest(cssX: number, cssY: number): boolean {
141	    const r = this.spriteRect;
142	    if (!r) return false;
143	    const kx = this.canvas.width / (this.canvas.clientWidth || 1);
144	    const ky = this.canvas.height / (this.canvas.clientHeight || 1);
145	    const x = cssX * kx, y = cssY * ky;
146	    if (x < r.x || x > r.x + r.w || y < r.y || y > r.y + r.h) return false;
147	    try {
148	      return this.ctx.getImageData(Math.floor(x), Math.floor(y), 1, 1).data[3] > 16;
149	    } catch {
150	      return true; // tainted canvas (no CORS): fall back to the rect test
151	    }
152	  }
153	
154	  constructor(private canvas: HTMLCanvasElement) {
155	    const c = canvas.getContext("2d");
156	    if (!c) throw new Error("no 2d context");
157	    this.ctx = c;
158	    this.ctx.imageSmoothingEnabled = false;
159	    this.scheduleFrame();
160	  }
161	
162	  /// Widest frame of each clip , scale is computed per CLIP (not per frame)
163	  /// so the pet doesn't pulse and the bubble doesn't bounce as frames of
164	  /// slightly different widths cycle.
165	  private clipMaxW: number[] = [];
166	
167	  load(spritesheetUrl: string) {
168	    if (spritesheetUrl === this.loadedUrl) return;
169	    this.loadedUrl = spritesheetUrl;
170	    const loadVersion = ++this.loadVersion;
171	    this.loaded = false;
172	    const img = new Image();
173	    img.crossOrigin = "anonymous"; // CDN sends CORS , lets us read alpha
174	    img.onload = () => {
175	      if (loadVersion !== this.loadVersion) return;
176	      this.img = img;
177	      this.clips = slice(img);
178	      this.clipMaxW = this.clips.map((clip) => Math.max(...clip.map((r) => r.w)));
179	      this.frame = 0;
180	      this.loaded = true;
181	    };
182	    // A pre-CORS cached copy makes the crossOrigin load fail , retry plain
183	    // (displayable, but slicing falls back to the fixed grid).
184	    img.onerror = () => {
185	      if (loadVersion !== this.loadVersion) return;
186	      // Diagnostics for the Windows build (debug.log via Rust).
187	      try {
188	        // @ts-ignore tauri global (withGlobalTauri)
189	        window.__TAURI__?.core?.invoke?.("log_debug", { msg: `sprite CORS load failed, plain retry: ${spritesheetUrl.slice(0, 80)}` });
190	      } catch {}
191	      const plain = new Image();
192	      plain.onload = () => {
193	        if (loadVersion !== this.loadVersion) return;
194	        this.img = plain;
195	        this.clips = [];
196	        this.frame = 0;
197	        this.loaded = true;
198	      };
199	      plain.onerror = () => {
200	        if (loadVersion === this.loadVersion) this.loadedUrl = null;
201	      };
202	      plain.src = spritesheetUrl;
203	    };
204	    // Cache-bust http(s) URLs so the request actually carries CORS headers
205	    // instead of replaying a cached non-CORS response.
206	    img.src = spritesheetUrl.startsWith("data:")
207	      ? spritesheetUrl
208	      : spritesheetUrl + (spritesheetUrl.includes("?") ? "&" : "?") + "cors=1";
209	  }
210	
211	  setState(state: string) {
212	    this.fps = STATE_FPS[state] ?? 3;
213	    // User binding (Settings → Pet → Animations) overrides the default row,
214	    // like the macOS PetBindings store.
215	    const bound = parseInt(localStorage.getItem(`ap_bind_${state}`) ?? "", 10);
216	    const row = Number.isFinite(bound) && bound >= 0 ? bound : (STATE_ROW[state] ?? 0);
217	    if (row !== this.row) { this.row = row; }
218	
219	    if (state === "idle") this.startIdleCycling();
220	    else this.stopIdleCycling();
221	  }
222	
223	  private startIdleCycling() {
224	    const clips = readIdleClips();
225	    const interval = readIdleIntervalMs();
226	    if (!clips) { this.stopIdleCycling(); return; }
227	    // Avoid restarting if the playlist is already running with the same clips
228	    // and interval. This matters because setState("idle") is called every 500ms.
229	    if (this.idleTimer && interval === this.idleIntervalMs && JSON.stringify(clips) === JSON.stringify(this.idleClips)) return;
230	    this.stopIdleCycling();
231	    this.idleClips = clips;
232	    this.idleIntervalMs = interval;
233	    this.idleIndex = 0;
234	    this.idleRow = clips[0];
235	    this.frame = 0;
236	    this.idleTimer = window.setInterval(() => this.advanceIdleClip(), interval);
237	  }
238	
239	  private advanceIdleClip() {
240	    if (!this.idleClips.length) return;
241	    const mode = localStorage.getItem(IDLE_MODE_KEY) ?? "random";
242	    if (mode === "random") {
243	      this.idleIndex = Math.floor(Math.random() * this.idleClips.length);
244	    } else {
245	      this.idleIndex = (this.idleIndex + 1) % this.idleClips.length;
246	    }
247	    this.idleRow = this.idleClips[this.idleIndex];
248	    this.frame = 0;
249	  }
250	
251	  private stopIdleCycling() {
252	    if (this.idleTimer) { clearInterval(this.idleTimer); this.idleTimer = null; }
253	    this.idleIntervalMs = 0;
254	    this.idleClips = [];
255	    this.idleIndex = 0;
256	    this.idleRow = null;
257	  }
258	
259	  /// Override the spritesheet row while roaming. setState still updates the
260	  /// mood row in the background so the override can be cleared cleanly.
261	  setRow(row: number) {
262	    if (this.overrideRow !== row) { this.overrideRow = row; this.frame = 0; }
263	  }
264	
265	  clearRow() {
266	    if (this.overrideRow !== null) { this.overrideRow = null; this.frame = 0; }
267	  }
268	
269	  /// The frames of the active row (override ?? mood), clamped to what the sheet
270	  /// actually has. Previously this used `this.row` and the override only
271	  /// affected `scaleW`, which meant roaming drew mood frames at walk-row width.
272	  private currentClip(activeRow: number): Rect[] | null {
273	    if (!this.clips.length) return null;
274	    return this.clips[Math.min(activeRow, this.clips.length - 1)];
275	  }
276	
277	  /// Frame loop driven by setTimeout (not requestAnimationFrame). The pet
278	  /// only needs 3-8 fps, so rAF's 60Hz wakeups were pure waste — each tick
279	  /// rescheduled the next one ~16ms later even when 300ms of idle time was
280	  /// available. setTimeout lets the event loop sleep between frames.
281	  private scheduleFrame() {
282	    const delay = Math.max(80, 1000 / this.fps);
283	    setTimeout(() => {
284	      if (this.loaded) {
285	        this.frame++;
286	        this.draw();
287	      }
288	      this.scheduleFrame();
289	    }, delay);
290	  }
291	
292	  private draw() {
293	    const { width: W, height: H } = this.canvas;
294	    this.ctx.clearRect(0, 0, W, H);
295	
296	    const activeRow = this.overrideRow ?? this.idleRow ?? this.row;
297	    if (activeRow !== this.lastDrawnRow) { this.lastDrawnRow = activeRow; this.frame = 0; }
298	
299	    let r: Rect;
300	    let scaleW: number; // width used for the scale , per CLIP, not per frame
301	    const clip = this.currentClip(activeRow);
302	    if (clip) {
303	      r = clip[this.frame % clip.length];
304	      scaleW = this.clipMaxW[Math.min(activeRow, this.clips.length - 1)] || r.w;
305	    } else {
306	      // Fallback: fixed 8x9 grid (pixels unreadable , e.g. no CORS).
307	      const fw = this.img.naturalWidth / COLS;
308	      const fh = this.img.naturalHeight / ROWS;
309	      if (!fw || !fh) return;
310	      r = { x: (this.frame % COLS) * fw, y: Math.min(activeRow, ROWS - 1) * fh, w: fw, h: fh };
311	      scaleW = fw;
312	    }
313	
314	    // Fit into the canvas, anchored bottom-center; snap to an integer scale so
315	    // pixel-art stays crisp. The scale comes from the clip's widest frame so
316	    // every frame of an animation renders at the SAME size (no pulsing, and a
317	    // stable headroom = the bubble above never bounces).
318	    const fit = Math.min(W / scaleW, H / r.h);
319	    const s = fit >= 1 ? Math.floor(fit) : fit;
320	    const dw = r.w * s, dh = r.h * s;
321	    this.headroom = (H - dh) / H;
322	    this.spriteRect = { x: (W - dw) / 2, y: H - dh, w: dw, h: dh };
323	    this.ctx.drawImage(this.img, r.x, r.y, r.w, r.h, (W - dw) / 2, H - dh, dw, dh);
324	  }
325	}
