  1	// Renders + animates a pet spritesheet on a canvas. Sheets are sliced with
  2	// alpha-gutter detection (a port of the macOS app's SpriteSlicer): transparent
  3	// gaps split the sheet into rows, then each row into frames. That way empty
  4	// cells in a row simply don't exist , the pet never blinks out on sparse rows,
  5	// and ragged/AI-generated sheets slice correctly. Falls back to a fixed 8x9
  6	// grid when pixels can't be read (no CORS).
  7	
  8	const COLS = 8;
  9	const ROWS = 9;
 10	const ALPHA_THRESHOLD = 16;
 11	
 12	// Row index per state, matching the macOS app's spritesheet layout:
 13	// 0 Idle, 1 RunRight, 2 RunLeft, 3 Waving, 4 Jumping, 5 Failed, 6 Waiting, 7 Running, 8 Review
 14	const STATE_ROW: Record<string, number> = {
 15	  idle: 0,
 16	  registered: 0,
 17	  working: 7,
 18	  waiting: 6,
 19	  done: 3,       // waving goodbye to the finished task
 20	  celebrate: 4,  // jumping , the 3s burst when all work completes
 21	};
 22	
 23	// Frame rate varies by mood (faster while working), like the macOS app.
 24	const STATE_FPS: Record<string, number> = {
 25	  working: 8,
 26	  celebrate: 8,
 27	  waiting: 4,
 28	  done: 3,
 29	  idle: 3,
 30	  registered: 3,
 31	};
 32	
 33	export interface Rect { x: number; y: number; w: number; h: number }
 34	
 35	// ---- Idle animation playlist (decoration / no-activity use) --------
 36	// When the pet sits in the "idle" mood with no active work, cycle through
 37	// a user-configured set of clips instead of looping one action forever.
 38	
 39	const IDLE_CLIPS_KEY = "ap_idle_clips";
 40	const IDLE_MODE_KEY = "ap_idle_mode";
 41	const IDLE_INTERVAL_KEY = "ap_idle_interval";
 42	const DEFAULT_IDLE_INTERVAL_S = 5;
 43	
 44	function readIdleClips(): number[] | null {
 45	  try {
 46	    const raw = localStorage.getItem(IDLE_CLIPS_KEY);
 47	    if (!raw) return null;
 48	    const v = JSON.parse(raw);
 49	    if (Array.isArray(v) && v.length) {
 50	      return v.filter((x) => Number.isFinite(x) && x >= 0).map((x) => Number(x));
 51	    }
 52	  } catch {}
 53	  return null;
 54	}
 55	
 56	function readIdleIntervalMs(): number {
 57	  try {
 58	    const n = Number.parseFloat(localStorage.getItem(IDLE_INTERVAL_KEY) ?? "");
 59	    if (Number.isFinite(n) && n >= 1) return Math.round(n * 1000);
 60	  } catch {}
 61	  return DEFAULT_IDLE_INTERVAL_S * 1000;
 62	}
 63	
 64	/// Contiguous runs of `true` in an occupancy array → [start, end) pairs.
 65	function segments(occ: Uint8Array): Array<[number, number]> {
 66	  const out: Array<[number, number]> = [];
 67	  let start = -1;
 68	  for (let i = 0; i < occ.length; i++) {
 69	    if (occ[i] && start < 0) start = i;
 70	    else if (!occ[i] && start >= 0) { out.push([start, i]); start = -1; }
 71	  }
 72	  if (start >= 0) out.push([start, occ.length]);
 73	  return out;
 74	}
 75	
 76	/// Alpha-gutter slice: rows by transparent bands, then frames within each row.
 77	export function slice(img: HTMLImageElement): Rect[][] {
 78	  const w = img.naturalWidth, h = img.naturalHeight;
 79	  if (!w || !h) return [];
 80	  const cv = document.createElement("canvas");
 81	  cv.width = w; cv.height = h;
 82	  const ctx = cv.getContext("2d", { willReadFrequently: true });
 83	  if (!ctx) return [];
 84	  ctx.drawImage(img, 0, 0);
 85	  let data: Uint8ClampedArray;
 86	  try {
 87	    data = ctx.getImageData(0, 0, w, h).data;
 88	  } catch {
 89	    return []; // tainted (no CORS) , caller falls back to the fixed grid
 90	  }
 91	  const rowHas = new Uint8Array(h);
 92	  for (let y = 0; y < h; y++) {
 93	    const off = y * w * 4;
 94	    for (let x = 0; x < w; x++) {
 95	      if (data[off + x * 4 + 3] > ALPHA_THRESHOLD) { rowHas[y] = 1; break; }
 96	    }
 97	  }
 98	  const clips: Rect[][] = [];
 99	  for (const [y0, y1] of segments(rowHas)) {
100	    const colHas = new Uint8Array(w);
101	    for (let y = y0; y < y1; y++) {
102	      const off = y * w * 4;
103	      for (let x = 0; x < w; x++) {
104	        if (data[off + x * 4 + 3] > ALPHA_THRESHOLD) colHas[x] = 1;
105	      }
106	    }
107	    const clip = segments(colHas).map(([x0, x1]) => ({ x: x0, y: y0, w: x1 - x0, h: y1 - y0 }));
108	    if (clip.length) clips.push(clip);
109	  }
110	  return clips;
111	}
