922	const KEY = "ap_lang";
923	
924	function detect(): Lang {
925	  try {
926	    const saved = localStorage.getItem(KEY);
927	    if (saved === "en" || saved === "vi" || saved === "zh" || saved === "zh-TW") return saved;
928	  } catch {}
929	  const n = (navigator.language || "en").toLowerCase();
930	  if (n.startsWith("vi")) return "vi";
931	  if (n === "zh-tw" || n === "zh-hk" || n === "zh-mo" || n.startsWith("zh-hant")) return "zh-TW";
932	  if (n.startsWith("zh")) return "zh";
933	  return "en";
934	}
935	
936	let lang: Lang = detect();
937	
938	export function getLang(): Lang {
939	  return lang;
940	}
941	
942	export function setLang(l: Lang) {
943	  lang = l;
944	  try { localStorage.setItem(KEY, l); } catch {}
945	}
946	
947	export function t(key: string): string {
948	  if (lang === "en") return key;
949	  return DICT[lang]?.[key] ?? key;
950	}

