1430	// The quick-bubble preset pool: one message per line, shared by the floating
1431	// ball (send menu) and left-click-on-pet (random line). Stored in localStorage
1432	// as a JSON array; the textarea shows raw text for easy editing.
1433	const QUICK_KEY = "ap_quick_bubbles";
1434	const QUICK_DEFAULTS = [
1435	  "Hello!",
1436	  "Coding…",
1437	  "Need a break?",
1438	  "What's up?",
1439	  "Let's ship something.",
1440	];
1441	function readQuickList(): string[] {
1442	  try {
1443	    const v = JSON.parse(localStorage.getItem(QUICK_KEY) || "[]");
1444	    return Array.isArray(v) ? v.filter((x: unknown) => typeof x === "string") : [];
1445	  } catch { return []; }
1446	}
1447	function writeQuickList(list: string[]) {
1448	  localStorage.setItem(QUICK_KEY, JSON.stringify(list));
1449	  emit("bubble-changed", null); // floating ball listens and refreshes its presets
1450	}
1451	function initQuickBubbles() {
1452	  const ta = document.getElementById("quick-bubbles") as HTMLTextAreaElement | null;
1453	  const reset = document.getElementById("quick-reset") as HTMLButtonElement | null;
1454	  if (!ta) return;
1455	  const current = readQuickList();
1456	  ta.value = (current.length ? current : QUICK_DEFAULTS).join("\n");
1457	  if (!current.length) writeQuickList(QUICK_DEFAULTS);
1458	  ta.addEventListener("change", () => {
1459	    const lines = ta.value.split("\n").map((s) => s.trim()).filter(Boolean);
1460	    writeQuickList(lines);
1461	  });
1462	  if (reset) reset.onclick = () => {
1463	    ta.value = QUICK_DEFAULTS.join("\n");
1464	    writeQuickList(QUICK_DEFAULTS);
1465	  };
1466	}
