     1	// Regression fuzz: climb mode must never get permanently stuck, regardless of
     2	// window layout. Historically the pet could freeze forever when a wander
     3	// target landed 6–8px away: moveToward stops at ARRIVAL_DISTANCE (8) while
     4	// advanceWander only picked a new target below 6px, so the pet stood still
     5	// every tick with no way to re-target.
     6	//
     7	// Fully deterministic (mulberry32 for layout AND Math.random), so a failure
     8	// here reproduces on every run.
     9	
    10	import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
    11	import { runMode } from "./modes";
    12	import type { Environment, Point } from "./types";
    13	
    14	vi.mock("@tauri-apps/api/window", () => ({
    15	  cursorPosition: vi.fn(),
    16	}));
    17	
    18	let storedRoamMode = "climb";
