    24	
    25	/// Deterministic PRNG so failures are reproducible.
    26	function mulberry32(seed: number) {
    27	  let a = seed >>> 0;
    28	  return () => {
    29	    a |= 0; a = (a + 0x6d2b79f5) | 0;
    30	    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    31	    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    32	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    33	  };
    34	}
