    36	const WORK_AREA = { left: 0, top: 0, right: 1920, bottom: 1040 };
    37	
    38	async function simulate(env: Environment, start: Point, ticks = 900): Promise<boolean> {
    39	  let pos = start;
    40	  let stallRun = 0;
    41	  let finalStuck = false;
    42	  const t0 = Date.now();
    43	  await runMode("wander", { env, pos, pet: pet as never }); // reset module state
    44	  const rng = mulberry32(7777); // deterministic Math.random for wander targets / direction flips
    45	  const spy = vi.spyOn(Math, "random").mockImplementation(rng);
    46	  try {
    47	    for (let i = 0; i < ticks; i++) {
    48	      vi.setSystemTime(t0 + i * 30);
    49	      const next = await runMode("climb", { env, pos, pet: pet as never });
    50	      const movedNow = next.x !== pos.x || next.y !== pos.y;
    51	      stallRun = movedNow ? 0 : stallRun + 1;
    52	      // Stuck only if completely still for the final 9s (resting pauses are <= 3.5s).
    53	      if (i > ticks - 300 && stallRun > 280) finalStuck = true;
    54	      pos = next;
    55	    }
    56	  } finally {
    57	    spy.mockRestore();
    58	  }
    59	  return finalStuck;
    60	}
