    66	  const top = Math.round((rnd() - 0.35) * 1600);
    67	  const left = Math.round((rnd() - 0.2) * 2100);
    68	  return { title: `W${i}`, rect: { left, top, right: left + w, bottom: top + h } };
    69	}
