    76	  afterEach(() => {
    77	    vi.useRealTimers();
    78	  });
    79	
    80	  it("random layouts x random starts (300 seeds)", async () => {
    81	    const stuck: Array<{ seed: number; start: Point; windows: unknown }> = [];
    82	    for (let seed = 0; seed < 300; seed++) {
    83	      const rnd = mulberry32(seed);
    84	      const nWin = 1 + Math.floor(rnd() * 5);
    85	      const windows = Array.from({ length: nWin }, (_, i) => randomWindow(rnd, i));
    86	      const env: Environment = { workArea: WORK_AREA, windows };
    87	      const start: Point = {
    88	        x: Math.round(rnd() * 1800),
    89	        y: Math.round(rnd() * 900),
    90	      };
    91	      const stuckNow = await simulate(env, start, 900);
    92	      if (stuckNow) {
    93	        stuck.push({ seed, start, windows });
    94	        if (stuck.length >= 5) break;
