  1	// Floating ball: a draggable desktop orb. Left-click opens a bubble menu,
  2	// right-click opens Settings, drag moves the window and persists its position
  3	// on release.
  4	
  5	import "./styles.css";
  6	
  7	import { invoke } from "@tauri-apps/api/core";
  8	import { emit, listen } from "@tauri-apps/api/event";
  9	import { cursorPosition, currentMonitor, getCurrentWindow, LogicalPosition, LogicalSize, PhysicalPosition } from "@tauri-apps/api/window";
 10	import { FloatingBallDragController } from "./floating-ball-drag";
 11	import { attachFloatingBallPointerDrag } from "./floating-ball-pointer";
 12	import { t, setLang, type Lang } from "./i18n";
 13	import { Pet } from "./pet";
 14	import { getLibrary } from "./catalog";
 15	import { loadPetStore, selectedPetInstance } from "./pets";
 16	
 17	const QUICK_KEY = "ap_quick_bubbles";
 18	const MAX_PRESETS = 12;
 19	
 20	const WIN_SIZE = 80;        // window is larger than the 56px orb so shadows/scale fit
 21	const MENU_W = 300;
 22	const MENU_H = 420;
 23	
 24	const ball = document.getElementById("ball") as HTMLDivElement;
 25	const menu = document.getElementById("ball-menu") as HTMLDivElement;
 26	const input = document.getElementById("bm-input") as HTMLInputElement;
 27	const presetsEl = document.getElementById("bm-presets") as HTMLDivElement;
 28	const sendBtn = document.getElementById("bm-send") as HTMLButtonElement;
 29	const cancelBtn = document.getElementById("bm-cancel") as HTMLButtonElement;
 30	
 31	const win = getCurrentWindow();
 32	const floatingBallDrag = new FloatingBallDragController({
 33	  cursorPosition,
 34	  setPosition: (position) => win.setPosition(new PhysicalPosition(position.x, position.y)),
 35	  persistPosition: () => invoke<void>("persist_floating_ball_position"),
 36	});
 37	
 38	let selectedPreset = -1;
 39	
 40	function readPresets(): string[] {
 41	  try {
 42	    const v = JSON.parse(localStorage.getItem(QUICK_KEY) || "[]");
 43	    return Array.isArray(v)
 44	      ? v.filter((x: unknown) => typeof x === "string" && x.trim()).slice(0, MAX_PRESETS)
 45	      : [];
 46	  } catch { return []; }
 47	}
 48	
 49	function writePresets(list: string[]) {
 50	  localStorage.setItem(QUICK_KEY, JSON.stringify(list.slice(0, MAX_PRESETS)));
 51	  void emit("bubble-changed", null);
 52	}
 53	
 54	function syncSend() {
 55	  sendBtn.disabled = !input.value.trim();
 56	}
 57	
 58	function createPresetButton(line: string, index: number) {
 59	  const btn = document.createElement("button");
 60	  btn.className = "bm-preset";
 61	  btn.textContent = line;
 62	  btn.title = t("Send to selected") + " · " + t("Shift-click to delete");
 63	  btn.onclick = (ev) => {
 64	    if (ev.shiftKey) {
 65	      const next = readPresets().filter((_, j) => j !== index);
 66	      writePresets(next);
 67	      selectedPreset = -1;
 68	      paintPresets();
 69	      syncSend();
 70	      return;
 71	    }
 72	    selectedPreset = index;
 73	    input.value = line;
 74	    paintPresets();
 75	    syncSend();
 76	    input.focus();
 77	  };
 78	  if (selectedPreset === index) btn.classList.add("sel");
 79	  return btn;
 80	}
 81	
 82	function paintPresets() {
 83	  const list = readPresets();
 84	  presetsEl.innerHTML = "";
 85	  if (!list.length) {
 86	    presetsEl.style.display = "none";
 87	    return;
 88	  }
 89	  presetsEl.style.display = "";
 90	  list.forEach((line, i) => presetsEl.appendChild(createPresetButton(line, i)));
 91	}
 92	
 93	function applyLangStrings() {
 94	  const bmTitle = document.getElementById("bm-title-text");
 95	  if (bmTitle) bmTitle.textContent = t("Quick bubble");
 96	  const bmHint = document.getElementById("bm-hint");
 97	  if (bmHint) bmHint.textContent = t("Shift-click to remove");
 98	  input.placeholder = t("Type a bubble message…");
 99	  cancelBtn.textContent = t("Cancel");
100	  sendBtn.textContent = t("Send");
101	  ball.title = t("Left-click: bubble · Right-click: settings · Drag to move");
102	}
103	
104	function shrinkToBall() {
105	  void win.setSize(new LogicalSize(WIN_SIZE, WIN_SIZE));
106	}
107	
108	/// Height delta between the menu window and the ball window.
109	const MENU_GROW = MENU_H - WIN_SIZE;
110	
111	async function showMenu() {
112	  if (!menu.hidden) return;
113	  input.value = "";
114	  selectedPreset = -1;
115	  paintPresets();
116	  syncSend();
117	
118	  const pos = await win.outerPosition();
119	  const sf = await win.scaleFactor();
120	  const mon = await currentMonitor();
121	  const work = mon?.workArea;
122	  const logicalX = pos.x / sf;
123	  const logicalY = pos.y / sf;
124	  const workLeft = work ? work.position.x / sf : logicalX;
125	  const workTop = work ? work.position.y / sf : logicalY;
126	  const workRight = work ? (work.position.x + work.size.width) / sf : logicalX + MENU_W;
127	  const workBottom = work ? (work.position.y + work.size.height) / sf : logicalY + MENU_H;
128	
129	  // If the menu would overflow the bottom, open UPWARD: the ball sticks to
